mapper.select:
SELECT pi.id, pi.image_url, pi.spu_no, pi.category, pi."name" AS productName, pi.grade AS grade, pi.property, pi.brand_name, Pi.charge_name, pi.project_charge_id, pi.approval_status, poi.project_status, pph.name as projectPhase, pott.approval_finish_task_count, pott.approval_task_count, pott.project_finish_task_count, pott.project_task_count, pi.progress_status, pott.total_task_count, pott.finished_count, pott.unfinished_count, pott.delay_finished_count, pott.delay_unfinished_count, pott.thisWeekTaskCount, pott.thisWeekFinishedCount, pott.thisWeekUnfinishedCount, poi.end_time AS planStartDate, poi.start_time AS planEndDate, CASE WHEN pott.finished_count = pott.total_task_count THEN to_date( pott.reality_end_time, 'YYYY-MM-dd' ) ELSE null END as actualFinishDate FROM product_info pi LEFT JOIN project_info poi ON pi.id = poi.product_id AND poi.is_deleted = FALSE LEFT JOIN ( SELECT pt.product_id, COALESCE(MIN(pp.seq), MAX(ppe.seq)) AS seq FROM project_task pt LEFT JOIN project_phase pp ON pt.phase_id = pp.id AND pt.product_id = pp.product_id AND pt.status IN (0,1,2,3,7,9,10) AND pp.is_deleted = FALSE LEFT JOIN project_phase ppe ON pt.phase_id = ppe.id AND pt.product_id = ppe.product_id AND pt.status = 4 AND ppe.is_deleted = FALSE WHERE pt.is_deleted = FALSE GROUP BY pt.product_id ) tpp ON pi.id = tpp.product_id LEFT JOIN project_phase pph ON tpp.product_id = pph.product_id AND pph.seq = tpp.seq AND pph.is_deleted = FALSE LEFT JOIN ( SELECT pot.product_id, SUM(CASE WHEN pot.status = 4 THEN 1 ELSE 0 END) AS finished_count, SUM(CASE WHEN pot.status <> 4 AND pot.status <> 5 THEN 1 ELSE 0 END) AS unfinished_count, SUM(CASE WHEN pot.status = 4 AND pot.plan_end_time < pot.reality_end_time THEN 1 ELSE 0 END) AS delay_finished_count, SUM(CASE WHEN pot.status <> 4 AND pot.status <> 5 AND pot.plan_end_time < current_date THEN 1 ELSE 0 END) AS delay_unfinished_count, SUM(CASE WHEN pot.property = 1 THEN 1 ELSE 0 END) AS approval_task_count, SUM(CASE WHEN (pot.status = 4 OR pot.status = 8) AND pot.property = 1 THEN 1 ELSE 0 END) AS approval_finish_task_count, SUM(CASE WHEN pot.property = 2 THEN 1 ELSE 0 END) AS project_task_count, SUM(CASE WHEN (pot.status = 4 OR pot.status = 8) AND pot.property = 2 THEN 1 ELSE 0 END) AS project_finish_task_count, SUM(CASE WHEN to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date >= to_char(date_trunc('week', current_date), 'YYYY-MM-dd') :: date AND to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date < to_char(date_trunc('week', now()) + INTERVAL '1 week', 'YYYY-MM-dd') :: date THEN 1 ELSE 0 END ) AS thisWeekTaskCount, SUM(CASE WHEN to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date >= to_char(date_trunc('week', current_date), 'YYYY-MM-dd') :: date AND to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date < to_char(date_trunc('week', now()) + INTERVAL '1 week', 'YYYY-MM-dd') :: date AND (pot.status = 4 OR pot.status = 8) THEN 1 ELSE 0 END ) AS thisWeekFinishedCount, SUM(CASE WHEN to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date >= to_char(date_trunc('week', current_date), 'YYYY-MM-dd') :: date AND to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date < to_char(date_trunc('week', now()) + INTERVAL '1 week', 'YYYY-MM-dd') :: date AND (pot.status <> 4 AND pot.status <> 5 AND pot.status <> 8) THEN 1 ELSE 0 END ) AS thisWeekUnfinishedCount, count(*) AS total_task_count, to_char(MAX(pot.reality_end_time), 'YYYY-MM-dd') AS reality_end_time FROM project_task pot WHERE pot.is_deleted = FALSE GROUP BY pot.product_id ) pott ON pott.product_id = pi.id WHERE pi.is_deleted = FALSE AND pi.is_finished_product_dev = 1
AND string_to_array(pi.charge_id,',') && string_to_array(#{params.chargeIdSplit},',')
AND pi.approval_status IN
#{item}
AND poi.project_status IN
#{item}
AND (pi."name" ILIKE concat('%', #{params.searchKeyword}::text ,'%') OR pi.spu_no ILIKE concat('%', #{params.searchKeyword}::text ,'%') OR pi.id IN (SELECT product_id FROM product_detail WHERE sku_no ILIKE concat('%', #{params.searchKeyword}::text ,'%') GROUP BY product_id) )
AND pi.category_id IN
#{item}
AND pi.grade_id IN
#{item}
AND pi.property_id IN
#{item}
AND pi.project_charge_id IN
#{item}
AND pi.charge_id IN
#{item}
AND pi.approval_status IN
#{item}
AND poi.project_status IN
#{item}
ORDER BY pi.create_time DESC

