us = 8) AND pot.property = 1 THEN 1 ELSE 0 END) AS approval_finish_task_count, SUM(CASE WHEN pot.property = 2 THEN 1 ELSE 0 END) AS project_task_count, SUM(CASE WHEN (pot.status = 4 OR pot.status = 8) AND pot.property = 2 THEN 1 ELSE 0 END) AS project_finish_task_count, SUM(CASE WHEN to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date >= to_char(date_trunc('week', current_date), 'YYYY-MM-dd') :: date AND to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date < to_char(date_trunc('week', now()) + INTERVAL '1 week', 'YYYY-MM-dd') :: date THEN 1 ELSE 0 END ) AS thisWeekTaskCount, SUM(CASE WHEN to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date >= to_char(date_trunc('week', current_date), 'YYYY-MM-dd') :: date AND to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date < to_char(date_trunc('week', now()) + INTERVAL '1 week', 'YYYY-MM-dd') :: date AND (pot.status = 4 OR pot.status = 8) THEN 1 ELSE 0 END ) AS thisWeekFinishedCount, SUM(CASE WHEN to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date >= to_char(date_trunc('week', current_date), 'YYYY-MM-dd') :: date AND to_char(pot.plan_end_time, 'YYYY-MM-dd') :: date < to_char(date_trunc('week', now()) + INTERVAL '1 week', 'YYYY-MM-dd') :: date AND (pot.status <> 4 AND pot.status <> 5 AND pot.status <> 8) THEN 1 ELSE 0 END ) AS thisWeekUnfinishedCount, count(*) AS total_task_count, to_char(MAX(pot.reality_end_time), 'YYYY-MM-dd') AS reality_end_time FROM project_task pot WHERE pot.is_deleted = FALSE GROUP BY pot.product_id ) pott ON pott.product_id = pi.id WHERE pi.is_deleted = FALSE AND pi.is_finished_product_dev = 1
